<script setup lang="ts">
import { computed,onMounted,ref } from 'vue'
import { ElSelect, ElOption, ElInputNumber, ElDatePicker, ElDialog } from 'element-plus'
import { useRouter } from 'vue-router'
import PlatformLayout from '../components/PlatformLayout.vue'
import { useApi,money,date,type Row } from '../composables/useApi'
const catalog=ref<Row>({NAME:'日常上门喂养',DESCRIPTION:'喂粮、换水、清理猫砂',ENABLED:true})
const {api,act}=useApi(),router=useRouter(),pets=ref<Row[]>([]),addresses=ref<Row[]>([]),slots=ref<Row[]>([]),sitters=ref<Row[]>([]),pet=ref(''),address=ref(''),selected=ref<Row|null>(null),day=ref(''),budget=ref(1000),open=ref(false),busy=ref(false),error=ref(''),key=ref('')
const filtered=computed(()=>slots.value.filter(s=>(!day.value||new Date(s.STARTS_AT).toLocaleDateString('sv-SE')===day.value)&&Number(s.PRICE_CENTS)<=budget.value*100))
async function load(){error.value='';try{[pets.value,addresses.value,slots.value,sitters.value,catalog.value]=await Promise.all([api<Row[]>('/pets'),api<Row[]>('/addresses'),api<Row[]>('/slots'),api<Row[]>('/sitters'),api('/service-catalog')])}catch(e){error.value=(e as Error).message}}
function choose(slot:Row){selected.value=slot;key.value=crypto.randomUUID();open.value=true}
async function book(){if(busy.value||!selected.value)return;busy.value=true;if(await act(()=>api('/orders','POST',{petId:pet.value,addressId:address.value,slotId:selected.value!.ID},{'Idempotency-Key':key.value}),'预约已创建，等待喂养员接单'))await router.push('/orders');else await load();busy.value=false}
onMounted(load)
</script>
<template><PlatformLayout><div class="page-heading"><div><span class="eyebrow">BOOK A VISIT</span><h1>预约上门服务</h1><p>{{ catalog.NAME }}：{{ catalog.DESCRIPTION }}</p></div><RouterLink to="/agent"><el-button>试试预约助手</el-button></RouterLink></div><el-alert v-if="error" :title="error" type="error" :closable="false"/><el-alert v-if="!pets.length||!addresses.length" title="预约前请先创建宠物档案和上门地址。" type="info" :closable="false"/><el-alert v-if="!catalog.ENABLED" title="当前服务暂时停止新预约。" :closable="false"/><section class="business-card"><div class="booking-filters"><el-date-picker v-model="day" type="date" value-format="YYYY-MM-DD" placeholder="服务日期"/><el-input-number v-model="budget" :min="1" :max="1000"/><span class="muted">预算上限 / 元</span><el-button @click="load">刷新时段</el-button></div><div class="profile-grid"><article v-for="s in filtered" :key="s.ID" class="profile-card"><h3>{{ s.SITTER_NAME }}</h3><p>{{ sitters.find(p=>p.ACCOUNT_ID===s.SITTER_ID)?.BIO }}</p><p>服务评分：{{ Number(sitters.find(p=>p.ACCOUNT_ID===s.SITTER_ID)?.RATING)>0 ? Number(sitters.find(p=>p.ACCOUNT_ID===s.SITTER_ID)?.RATING).toFixed(1)+' / 5' : '暂无评价' }}</p><p>{{ date(s.STARTS_AT) }}<br/>至 {{ date(s.ENDS_AT) }}</p><div class="quote-price">{{ money(s.PRICE_CENTS) }}<small> / 次</small></div><el-button type="primary" :disabled="!pets.length||!addresses.length||!catalog.ENABLED" @click="choose(s)">选择并预约</el-button></article></div><el-empty v-if="!filtered.length" description="暂时没有匹配时段，请调整条件。"/></section><el-dialog v-model="open" title="确认预约信息" width="min(520px, 92vw)" :close-on-click-modal="!busy"><el-form label-position="top"><el-form-item label="宠物"><el-select v-model="pet" placeholder="选择本次照顾的宠物"><el-option v-for="p in pets" :key="p.ID" :label="p.NAME" :value="p.ID"/></el-select></el-form-item><el-form-item label="上门地址"><el-select v-model="address" placeholder="选择本次上门地址"><el-option v-for="a in addresses" :key="a.ID" :label="`${a.CONTACT} · ${a.REGION} ${a.DETAIL}`" :value="a.ID"/></el-select></el-form-item><p>{{ selected?.SITTER_NAME }} · {{ selected && date(selected.STARTS_AT) }}</p><p class="quote-price">{{ selected && money(selected.PRICE_CENTS) }}</p><p class="muted">喂养员会根据上门地址和报价决定接单或拒单。提交时重新校验时段与报价。</p><el-button type="primary" :loading="busy" :disabled="!pet||!address" @click="book">确认创建预约</el-button></el-form></el-dialog></PlatformLayout></template>
